Here's a custom React hook that tracks whether the user is online:

```javascript
import { useState, useEffect } from 'react';

function useOnlineStatus() {
    const [isOnline, setIsOnline] = useState(navigator.onLine);

    useEffect(() => {
        const handleOnline = () => setIsOnline(true);
        const handleOffline = () => setIsOnline(false);

        window.addEventListener('online', handleOnline);
        window.addEventListener('offline', handleOffline);

        // Cleanup on unmount
        return () => {
            window.removeEventListener('online', handleOnline);
            window.removeEventListener('offline', handleOffline);
        };
    }, []);

    return isOnline;
}

export default useOnlineStatus;

// Usage:
// function MyComponent() {
//     const isOnline = useOnlineStatus();
//     return (
//         <div>
//             {isOnline 
//                 ? <p>You are online ✓</p> 
//                 : <p>You are offline - some features may not work</p>
//             }
//         </div>
//     );
// }
```

This hook uses the browser's `navigator.onLine` property and the `online`/`offline` events to track connection status. It initializes with the current state and updates reactively when the user's network status changes. The cleanup function removes event listeners when the component unmounts.
